export function createCommentHTML(n,e){const t=n&&"mevcut_kullanici"===n.user;return`\n    <div class="lk-comment-item lk-comment-row" data-index="${e}">\n      <img src="${n&&n.avatar||"images/profiller-img.png"}" alt="${n&&n.user||"kullanıcı"}" class="lk-avatar-sm lk-comment-avatar">\n      <div class="lk-comment-content lk-comment-details">\n        <h6 class="lk-comment-user"><a href="#">${n&&n.user||""}</a></h6>\n        <p class="lk-comment-text">${n&&n.text||""}</p>\n        <div class="lk-comment-footer" style="display: flex; align-items: center; gap: 12px; margin-top: 6px;">\n          <span class="lk-comment-meta lk-btn-reply" data-user="${n&&n.user||""}" style="font-size: 13px; color: #777; cursor: pointer;">Yanıtla</span>\n          <button class="lk-btn-like" type="button" style="background: none; border: none; padding: 0; cursor: pointer;">\n            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#777" stroke-width="2">\n              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>\n            </svg>\n          </button>\n          ${t?`<button class="lk-btn-delete-comment" data-index="${e}" type="button" style="background:none; border:none; color:#ef4444; font-size:12px; cursor:pointer; margin-left: auto;">Sil</button>`:""}\n        </div>\n      </div>\n    </div>\n  `}export function renderPostDetail(n){if(!n)return;const e=document.querySelector(".lk-detail-img-box img");e&&n.imageUrl&&(e.src=n.imageUrl);const t=document.querySelector(".lk-product-list");t&&n.products&&(t.innerHTML=n.products.map(n=>`\n      <li class="urunler">\n        <img class="etiket-isaret" src="images/etiket-isaret.svg" alt="Etiket">\n        <span class="etiket">${n.category}</span>\n        <strong class="marka">${n.brand}</strong>\n        ${n.link?`<a href="${n.link}" class="link-icon" target="_blank"><img src="images/link.svg" alt="Link"></a>`:""}\n      </li>\n    `).join(""));const s=document.querySelector(".lk-comment-list");s&&n.comments&&(s.innerHTML=n.comments.map((n,e)=>createCommentHTML(n,e)).join(""));const a=document.querySelector(".lk-dupe-list");a&&n.dupes&&(a.innerHTML=n.dupes.map(n=>`\n      <div class="lk-dupe-item">\n        <img src="${n.avatar||"images/profiller-img.png"}" alt="${n.user}" class="lk-avatar-sm">\n        <div class="lk-dupe-content">\n          <h6 class="lk-dupe-user"><a href="#">${n.user}</a></h6>\n          <ul class="lk-dupe-products">\n            ${(n.items||[]).map(n=>`\n              <li>\n                <img class="etiket-isaret" src="images/etiket-isaret.svg" alt="Etiket">\n                <span>${n.category}</span>\n                <span class="lk-brand">${n.brand}</span>\n                <div class="lk-item-actions">\n                  ${n.link?`\n                    <a href="${n.link}" class="link-icon" target="_blank">\n                      <img src="images/link.svg" alt="Link">\n                    </a>`:""} ${n.image?` <a href="${n.image}" class="gorsel-icon" target="_blank" rel="noopener noreferrer">\n                      <img src="images/görsel-icon.svg" alt="Görsel">\n                    </a>`:""}\n                </div>\n              </li>\n            `).join("")}\n          </ul>\n        </div>\n      </div>\n    `).join(""))}